<?php
 namespace App\Http\Controllers; use App\System; use App\Library\Geetest; use Illuminate\Foundation\Bus\DispatchesJobs; use Illuminate\Http\Response; use Illuminate\Routing\Controller as BaseController; use Illuminate\Foundation\Validation\ValidatesRequests; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; class Controller extends BaseController { use AuthorizesRequests, DispatchesJobs, ValidatesRequests; public function getCaptcha() { $driver = System::_get('vcode_driver'); if ($driver === 'code') { return response([]); } elseif ($driver === 'geetest') { return response(Geetest\API::get()); } elseif ($driver === 'recaptcha') { } return response([], Response::HTTP_NOT_IMPLEMENTED); } function validateCaptcha(Request $request) { $driver = System::_get('vcode_driver'); if ($driver === 'code') { $this->validate($request, [ 'captcha.key' => 'required|string', 'captcha.code' => 'required|captcha_api:' . $request->input('captcha.key') ]); } elseif ($driver === 'geetest') { $this->validate($request, [ 'captcha.a' => 'required|string', 'captcha.b' => 'required|string', 'captcha.c' => 'required|string', 'captcha.d' => 'required|string' ]); if (!Geetest\API::verify( $request->input('captcha.a'), $request->input('captcha.b'), $request->input('captcha.c'), $request->input('captcha.d'))) { throw \Illuminate\Validation\ValidationException::withMessages([ 'captcha' => [trans('validation.captcha')], ]); } } elseif ($driver === 'recaptcha') { $this->validate($request, [ 'captcha.t' => 'required|string' ]); } } function authQuery(Request $request, $model, $user_id_key = 'user_id', $post_key = 'user_id') { return $model::where($user_id_key, \Auth::id()); } protected function getUserId(Request $request, $post_key = 'user_id') { return \Auth::id(); } protected function getUserIdOrFail(Request $request, $post_key = 'user_id') { $user_id = self::getUserId($request, $post_key); if ($user_id) { return $user_id; } else { throw new \Exception('参数缺少 ' . $post_key); } } protected function getUser(Request $request) { return \Auth::user(); } protected function checkIsInMaintain() { if (System::_getInt('maintain') === 1) { $maintain_info = System::_get('maintain_info'); echo view('message', [ 'title' => '维护中', 'message' => $maintain_info ]); exit; } } protected function msg($message, $title = null, $exception = null) { return view('message', ['message' => $message, 'title' => $title, 'exception' => $exception]); } } 